import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"CLI 命令参考","description":"","frontmatter":{"title":"CLI 命令参考","docId":"developer.cli","translationKey":"developer.cli","locale":"zh","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6bb485d6e8067cb1639fb20821c45b79941245692f0b6c7525f2b3bee930048b","translationRevision":"b45310d1a33614d65aa5a1d180d6c4fe4f1b7ba10562694c98481169d9ac5b19","order":75},"headers":[],"relativePath":"zh/developer/cli.md","filePath":"zh/developer/cli.md","lastUpdated":1795727787000}`),a={name:`zh/developer/cli.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="cli-command-reference" tabindex="-1">CLI 命令参考 <a class="header-anchor" href="#cli-command-reference" aria-label="Permalink to “CLI 命令参考”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前提 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目标与前提”">​</a></h2><p>无需阅读 Rust 源码或解析人类可读的帮助输出，即可发现每个 <code>tiktools</code> 命令形式。需要一个匹配的已编译 <code>tiktools</code> 二进制文件；本参考完全离线，从不需要运行中的 host。权威来源是 <code>crates/tiktools-cli/src/commands/spec.rs</code> 中的命令规范注册表；每个领域模块拥有其解析器在错误中报告的用法字符串，因此本参考不会与解析器实际接受的语法产生偏差。</p><h2 id="inspect-help-offline" tabindex="-1">离线检查帮助 <a class="header-anchor" href="#inspect-help-offline" aria-label="Permalink to “离线检查帮助”">​</a></h2><p>人类可读的帮助按领域对动词分组；过滤参数只显示单个领域部分。<code>--json</code> 形式打印机器可读的注册表，这是每个代理应该优先使用的方式：每个动词的用法、摘要和破坏性标记，加上全局 CLI 约定，由顶层 <code>schema</code> 字段进行版本控制。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>用法错误只打印相关的命令形式并附带提示，而不是整页内容，因此输入错误永远不会滚动终端。退出码 2 始终表示用法错误；有关 host 解析、输出和密钥遮蔽规则，请参阅约定页脚。</p><h2 id="generated-command-reference" tabindex="-1">生成的命令参考 <a class="header-anchor" href="#generated-command-reference" aria-label="Permalink to “生成的命令参考”">​</a></h2><p>从 <code>docs/contracts/cli-help.json</code> 中签入的 CLI 帮助快照生成；二进制文件仍然是权威来源。用法行是解析器语法，在所有语言环境中保持英文；摘要和约定来自 CLI 自身的翻译目录，因此本参考不会与 <code>tiktools help</code> 以相同语言打印的内容产生偏差。标记为破坏性的动词会修改或销毁状态；脚本在执行前应进行确认。</p><p><code>tiktools [--json] [--standalone] &lt;command&gt; [args]</code></p><h3 id="tiktools-plugin-—-安装和管理插件" tabindex="-1"><code>tiktools plugin</code> — 安装和管理插件 <a class="header-anchor" href="#tiktools-plugin-—-安装和管理插件" aria-label="Permalink to “tiktools plugin — 安装和管理插件”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>列出已安装的插件</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>读取一个插件</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>从文件、id@version 或 url 安装</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>卸载插件 <strong>破坏性</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>在注册表中搜索软件包</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>安装前检查软件包规格</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>列出有可用更新的已安装插件</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>更新一个插件</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>更新所有过时的插件</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>回滚到以前的版本 <strong>破坏性</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>列出插件的可用版本</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>将插件固定到当前版本</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>移除版本固定</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>设置通道和自动更新策略</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>列出软件包任务</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>检查一个软件包任务</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>取消正在运行的软件包任务 <strong>破坏性</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>启用插件</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>禁用插件</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>启动插件</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>停止插件 <strong>破坏性</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>读取插件设置</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>写入插件设置</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>重置插件设置 <strong>破坏性</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>插件健康检查</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>动作类型或字段的选项</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>运行插件动作</td></tr><tr><td><code>tiktools plugin commands</code></td><td>列出已安装插件贡献的命令</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>描述一个贡献的命令</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>调用插件贡献的命令</td></tr></tbody></table><h3 id="tiktools-cloud-—-云账户和便携式备份-恢复-用-tiktools-cloud-origin-覆盖" tabindex="-1"><code>tiktools cloud</code> — 云账户和便携式备份/恢复（用 TIKTOOLS_CLOUD_ORIGIN 覆盖） <a class="header-anchor" href="#tiktools-cloud-—-云账户和便携式备份-恢复-用-tiktools-cloud-origin-覆盖" aria-label="Permalink to “tiktools cloud — 云账户和便携式备份/恢复（用 TIKTOOLS_CLOUD_ORIGIN 覆盖）”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools cloud status</code></td><td>云账户状态</td></tr><tr><td><code>tiktools cloud login</code></td><td>通过系统浏览器登录</td></tr><tr><td><code>tiktools cloud logout</code></td><td>退出登录 <strong>破坏性</strong></td></tr><tr><td><code>tiktools cloud restore</code></td><td>恢复云会话</td></tr><tr><td><code>tiktools cloud backup create [--out FILE]</code></td><td>写入便携式备份存档</td></tr><tr><td><code>tiktools cloud backup preview &lt;file&gt;</code></td><td>检查备份存档</td></tr><tr><td><code>tiktools cloud backup restore &lt;file&gt; [--yes]</code></td><td>恢复备份存档 <strong>破坏性</strong></td></tr></tbody></table><h3 id="tiktools-publisher-—-云发布者流程-需要登录" tabindex="-1"><code>tiktools publisher</code> — 云发布者流程（需要登录） <a class="header-anchor" href="#tiktools-publisher-—-云发布者流程-需要登录" aria-label="Permalink to “tiktools publisher — 云发布者流程（需要登录）”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools publisher list</code></td><td>列出发布者命名空间</td></tr><tr><td><code>tiktools publisher create &lt;namespace&gt;</code></td><td>创建发布者命名空间</td></tr><tr><td><code>tiktools publisher delete &lt;namespace-or-publisher-id&gt;</code></td><td>删除命名空间或发布者 <strong>破坏性</strong></td></tr><tr><td><code>tiktools publisher keys &lt;publisher-id&gt;</code></td><td>列出发布者的签名密钥</td></tr><tr><td><code>tiktools publisher enroll &lt;publisher-id&gt; [--key-id &lt;id&gt;]</code></td><td>登记发布者密钥；从 stdin 读取后端密码</td></tr><tr><td><code>tiktools publisher upload &lt;publisher-id&gt; &lt;path&gt;</code></td><td>上传插件包</td></tr><tr><td><code>tiktools publisher submit &lt;upload-id&gt; &lt;publisher-key-id&gt; &lt;plugin-id&gt; &lt;version&gt; [--target any]</code></td><td>提交上传以供审核</td></tr><tr><td><code>tiktools publisher release &lt;release-id&gt;</code></td><td>创建发布</td></tr><tr><td><code>tiktools publisher publish &lt;release-id&gt;</code></td><td>发布一个 release</td></tr></tbody></table><h3 id="tiktools-registry-—-软件包注册表和云目录" tabindex="-1"><code>tiktools registry</code> — 软件包注册表和云目录 <a class="header-anchor" href="#tiktools-registry-—-软件包注册表和云目录" aria-label="Permalink to “tiktools registry — 软件包注册表和云目录”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>列出已配置的注册表</td></tr><tr><td><code>tiktools registry refresh</code></td><td>刷新注册表元数据</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>显示一个注册表软件包</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>搜索云目录</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>云目录摘要页</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>云目录软件包的版本</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>云目录的分页能力</td></tr><tr><td><code>tiktools registry defaults</code></td><td>默认注册表配置</td></tr></tbody></table><h3 id="tiktools-processor-—-事件处理器" tabindex="-1"><code>tiktools processor</code> — 事件处理器 <a class="header-anchor" href="#tiktools-processor-—-事件处理器" aria-label="Permalink to “tiktools processor — 事件处理器”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>列出处理器</td></tr><tr><td><code>tiktools processor status</code></td><td>处理器管道状态</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>对示例事件运行一个处理器</td></tr></tbody></table><h3 id="tiktools-live-—-tiktok-live-连接" tabindex="-1"><code>tiktools live</code> — TikTok LIVE 连接 <a class="header-anchor" href="#tiktools-live-—-tiktok-live-连接" aria-label="Permalink to “tiktools live — TikTok LIVE 连接”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools live connect --unique-id &lt;id&gt; --session-cookie &lt;cookie&gt; [--room-id &lt;id&gt;]</code></td><td>连接到直播房间</td></tr><tr><td><code>tiktools live pick --session-cookie &lt;cookie&gt;</code></td><td>交互式选择直播房间</td></tr><tr><td><code>tiktools live channels [--keyword text] [--offset N] [--limit N] [--session-cookie &lt;cookie&gt;]</code></td><td>发现直播频道；无需会话即可工作</td></tr><tr><td><code>tiktools live disconnect</code></td><td>断开当前房间的连接 <strong>破坏性</strong></td></tr><tr><td><code>tiktools live status</code></td><td>当前连接状态</td></tr></tbody></table><h3 id="tiktools-points-—-观众忠诚度积分" tabindex="-1"><code>tiktools points</code> — 观众忠诚度积分 <a class="header-anchor" href="#tiktools-points-—-观众忠诚度积分" aria-label="Permalink to “tiktools points — 观众忠诚度积分”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools points config get</code></td><td>读取积分配置</td></tr><tr><td><code>tiktools points config set k=v...</code></td><td>更新积分配置</td></tr><tr><td><code>tiktools points viewer get &lt;id&gt;</code></td><td>读取一位观众的余额</td></tr><tr><td><code>tiktools points adjust &lt;id&gt; &lt;delta&gt;</code></td><td>为观众增加或减少积分</td></tr><tr><td><code>tiktools points leaderboard [--limit N]</code></td><td>按余额排名的观众</td></tr><tr><td><code>tiktools points reset [id]</code></td><td>重置一位观众或所有余额 <strong>破坏性</strong></td></tr></tbody></table><h3 id="tiktools-ranking-—-观众排名定义和状态" tabindex="-1"><code>tiktools ranking</code> — 观众排名定义和状态 <a class="header-anchor" href="#tiktools-ranking-—-观众排名定义和状态" aria-label="Permalink to “tiktools ranking — 观众排名定义和状态”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools ranking list</code></td><td>列出排名定义</td></tr><tr><td><code>tiktools ranking metrics</code></td><td>排名定义可用的指标</td></tr><tr><td><code>tiktools ranking create --record &lt;json&amp;#124;@file&gt;</code></td><td>创建排名定义</td></tr><tr><td><code>tiktools ranking update --record &lt;json&amp;#124;@file&gt;</code></td><td>更新排名定义</td></tr><tr><td><code>tiktools ranking get &lt;id&gt;</code></td><td>读取一个排名</td></tr><tr><td><code>tiktools ranking snapshot &lt;id&gt;</code></td><td>排名的当前排名情况</td></tr><tr><td><code>tiktools ranking delete &lt;id&gt;</code></td><td>删除排名 <strong>破坏性</strong></td></tr><tr><td><code>tiktools ranking reset &lt;id&gt;</code></td><td>重置累积状态 <strong>破坏性</strong></td></tr><tr><td><code>tiktools ranking pause &lt;id&gt;</code></td><td>暂停累积</td></tr><tr><td><code>tiktools ranking resume &lt;id&gt;</code></td><td>恢复累积</td></tr><tr><td><code>tiktools ranking contribute --record &lt;json&amp;#124;@file&gt;</code></td><td>添加外部贡献</td></tr></tbody></table><h3 id="tiktools-competition-—-定时观众竞赛" tabindex="-1"><code>tiktools competition</code> — 定时观众竞赛 <a class="header-anchor" href="#tiktools-competition-—-定时观众竞赛" aria-label="Permalink to “tiktools competition — 定时观众竞赛”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools competition list</code></td><td>列出竞赛</td></tr><tr><td><code>tiktools competition get &lt;id&gt;</code></td><td>读取一个竞赛</td></tr><tr><td><code>tiktools competition create --record &lt;json&amp;#124;@file&gt;</code></td><td>创建竞赛</td></tr><tr><td><code>tiktools competition update --record &lt;json&amp;#124;@file&gt;</code></td><td>更新竞赛</td></tr><tr><td><code>tiktools competition delete &lt;id&gt;</code></td><td>删除竞赛 <strong>破坏性</strong></td></tr><tr><td><code>tiktools competition state &lt;id&gt;</code></td><td>当前竞赛状态</td></tr><tr><td><code>tiktools competition results &lt;id&gt;</code></td><td>最终或中间结果</td></tr><tr><td><code>tiktools competition action --record &lt;json&amp;#124;@file&gt;</code></td><td>记录竞赛动作</td></tr><tr><td><code>tiktools competition mark-action-uncertain --record &lt;json&amp;#124;@file&gt;</code></td><td>将动作标记为不确定</td></tr><tr><td><code>tiktools competition resolve-action --record &lt;json&amp;#124;@file&gt;</code></td><td>解决不确定的动作</td></tr><tr><td><code>tiktools competition start &lt;id&gt;</code></td><td>开始竞赛</td></tr><tr><td><code>tiktools competition finish &lt;id&gt;</code></td><td>结束竞赛 <strong>破坏性</strong></td></tr><tr><td><code>tiktools competition candidates &lt;id&gt;</code></td><td>获胜者候选人</td></tr><tr><td><code>tiktools competition select-winner --record &lt;json&amp;#124;@file&gt;</code></td><td>选择获胜者</td></tr><tr><td><code>tiktools competition pause &lt;id&gt;</code></td><td>暂停竞赛</td></tr><tr><td><code>tiktools competition resume &lt;id&gt;</code></td><td>恢复竞赛</td></tr><tr><td><code>tiktools competition cancel &lt;id&gt;</code></td><td>取消竞赛 <strong>破坏性</strong></td></tr></tbody></table><h3 id="tiktools-automation-—-事件和动作自动化规则" tabindex="-1"><code>tiktools automation</code> — 事件和动作自动化规则 <a class="header-anchor" href="#tiktools-automation-—-事件和动作自动化规则" aria-label="Permalink to “tiktools automation — 事件和动作自动化规则”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools automation list [--kind event&amp;#124;action&amp;#124;all]</code></td><td>列出自动化规则</td></tr><tr><td><code>tiktools automation context [--event-type t]</code></td><td>规则可用的模板上下文</td></tr><tr><td><code>tiktools automation get &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>读取一条规则</td></tr><tr><td><code>tiktools automation create --record json [--kind event&amp;#124;action]</code></td><td>创建规则</td></tr><tr><td><code>tiktools automation update &lt;id&gt; --record json [--kind event&amp;#124;action]</code></td><td>更新规则</td></tr><tr><td><code>tiktools automation delete &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>删除规则 <strong>破坏性</strong></td></tr><tr><td><code>tiktools automation enable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>启用规则</td></tr><tr><td><code>tiktools automation disable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>禁用规则</td></tr><tr><td><code>tiktools automation test (--id &lt;id&gt; &amp;#124; --record json) [--kind event&amp;#124;action] [--trigger t] [--event json]</code></td><td>对示例事件空跑一条规则</td></tr><tr><td><code>tiktools automation fire --trigger &lt;type&gt; [--event json] [--record json]</code></td><td>手动触发触发器</td></tr><tr><td><code>tiktools automation moderation-penalty --points &lt;delta&gt;</code></td><td>以积分施加管理处罚</td></tr></tbody></table><h3 id="tiktools-globals-—-插件间共享的键-值全局变量" tabindex="-1"><code>tiktools globals</code> — 插件间共享的键/值全局变量 <a class="header-anchor" href="#tiktools-globals-—-插件间共享的键-值全局变量" aria-label="Permalink to “tiktools globals — 插件间共享的键/值全局变量”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools globals list</code></td><td>列出所有全局键</td></tr><tr><td><code>tiktools globals get &lt;key&gt;</code></td><td>读取一个全局变量</td></tr><tr><td><code>tiktools globals set &lt;key&gt; &lt;value&gt;</code></td><td>写入一个全局变量</td></tr><tr><td><code>tiktools globals delete &lt;key&gt;</code></td><td>删除一个全局变量 <strong>破坏性</strong></td></tr></tbody></table><h3 id="tiktools-workflow-—-可视化工作流图" tabindex="-1"><code>tiktools workflow</code> — 可视化工作流图 <a class="header-anchor" href="#tiktools-workflow-—-可视化工作流图" aria-label="Permalink to “tiktools workflow — 可视化工作流图”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools workflow list</code></td><td>列出已保存的工作流图</td></tr><tr><td><code>tiktools workflow get &lt;id&gt;</code></td><td>读取一个图</td></tr><tr><td><code>tiktools workflow save --record json</code></td><td>创建或替换图</td></tr><tr><td><code>tiktools workflow delete &lt;id&gt;</code></td><td>删除图 <strong>破坏性</strong></td></tr><tr><td><code>tiktools workflow enable &lt;id&gt;</code></td><td>启用图</td></tr><tr><td><code>tiktools workflow disable &lt;id&gt;</code></td><td>禁用图</td></tr></tbody></table><h3 id="tiktools-media-—-媒体文件验证和播放" tabindex="-1"><code>tiktools media</code> — 媒体文件验证和播放 <a class="header-anchor" href="#tiktools-media-—-媒体文件验证和播放" aria-label="Permalink to “tiktools media — 媒体文件验证和播放”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools media validate &lt;path&gt; [--kind audio&amp;#124;video&amp;#124;image&amp;#124;other]</code></td><td>在动作中使用前验证媒体文件</td></tr></tbody></table><h3 id="tiktools-system-—-主机信息和诊断" tabindex="-1"><code>tiktools system</code> — 主机信息和诊断 <a class="header-anchor" href="#tiktools-system-—-主机信息和诊断" aria-label="Permalink to “tiktools system — 主机信息和诊断”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools system info</code></td><td>主机版本和运行时信息</td></tr><tr><td><code>tiktools system health</code></td><td>组件健康报告</td></tr><tr><td><code>tiktools system snapshot</code></td><td>用于调试的完整状态快照</td></tr><tr><td><code>tiktools system doctor</code></td><td>诊断常见的设置问题</td></tr><tr><td><code>tiktools system request-input-access</code></td><td>向桌面用户请求输入访问权限</td></tr><tr><td><code>tiktools system shutdown</code></td><td>关闭运行中的主机 <strong>破坏性</strong></td></tr></tbody></table><h3 id="tiktools-template-—-可重用的自动化模板和配置文件" tabindex="-1"><code>tiktools template</code> — 可重用的自动化模板和配置文件 <a class="header-anchor" href="#tiktools-template-—-可重用的自动化模板和配置文件" aria-label="Permalink to “tiktools template — 可重用的自动化模板和配置文件”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools template import &lt;file&gt; [--param k=v]... [--event-name n] [--action-name n] [--dry-run] [--no-save] [--disabled]</code></td><td>将模板导入为自动化规则</td></tr><tr><td><code>tiktools template export --event &lt;id&gt; --out &lt;file&gt; [--title t] [--id template-id]</code></td><td>将事件规则导出为模板</td></tr><tr><td><code>tiktools template list</code></td><td>列出模板库中的模板</td></tr><tr><td><code>tiktools template delete &lt;template-id&gt;</code></td><td>删除模板 <strong>破坏性</strong></td></tr><tr><td><code>tiktools template profile-import &lt;file&gt; [--param k=v]... [--dry-run] [--no-save] [--disabled]</code></td><td>导入完整的自动化配置文件</td></tr><tr><td><code>tiktools template profile-export --out &lt;file&gt; [--name n]</code></td><td>导出自动化配置文件</td></tr></tbody></table><h3 id="tiktools-api-—-面向代理的通用控制面-覆盖主机方法" tabindex="-1"><code>tiktools api</code> — 面向代理的通用控制面，覆盖主机方法 <a class="header-anchor" href="#tiktools-api-—-面向代理的通用控制面-覆盖主机方法" aria-label="Permalink to “tiktools api — 面向代理的通用控制面，覆盖主机方法”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools api discover [--format json&amp;#124;human]</code></td><td>从主机注册表实时列出所有方法</td></tr><tr><td><code>tiktools api schema &lt;method&gt; [--format json&amp;#124;human]</code></td><td>一个方法的描述、标志和架构</td></tr><tr><td><code>tiktools api call &lt;method&gt; [params-json] [--timeout SEC] [--dry-run] [--confirm] [--redact&amp;#124;--secrets-visible] [--explain] [--format json&amp;#124;human] [--expected-revision N] [--command-id ID --host-instance-id ID] [--include-meta]</code></td><td>验证并执行一个方法；破坏性方法需要 --confirm</td></tr><tr><td><code>tiktools api events [--topics t,...] [--timeout SEC] [--max-events N]</code></td><td>流式传输 NDJSON 域事件</td></tr><tr><td><code>tiktools api event get &lt;name&gt; [--type kind]... [--author text] [--limit N]</code></td><td>搜索有界动态日志</td></tr><tr><td><code>tiktools api verify [--coverage&amp;#124;--smoke] [--sandbox] [--timeout SEC]</code></td><td>针对主机验证控制面</td></tr></tbody></table><h3 id="tiktools-host-—-无界面主机运行时和原始-rpc-直通" tabindex="-1"><code>tiktools host</code> — 无界面主机运行时和原始 rpc 直通 <a class="header-anchor" href="#tiktools-host-—-无界面主机运行时和原始-rpc-直通" aria-label="Permalink to “tiktools host — 无界面主机运行时和原始 rpc 直通”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools host --stdio [--events]</code></td><td>stdio 上的无界面主机；用 --events 流式传输事件</td></tr><tr><td><code>tiktools host --ipc</code></td><td>本地 IPC 上的无界面主机；有主机运行时拒绝启动</td></tr><tr><td><code>tiktools rpc &lt;method&gt; [params-json] &amp;#124; rpc --stdio [--events]</code></td><td>到任何主机方法的无类型直通</td></tr><tr><td><code>tiktools rpc --stdio [--events]</code></td><td>stdio 上的 NDJSON 请求/响应循环</td></tr></tbody></table><h3 id="tiktools-web-—-本地浏览器适配器-需要-local-web-特性" tabindex="-1"><code>tiktools web</code> — 本地浏览器适配器（需要 local-web 特性） <a class="header-anchor" href="#tiktools-web-—-本地浏览器适配器-需要-local-web-特性" aria-label="Permalink to “tiktools web — 本地浏览器适配器（需要 local-web 特性）”">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools web --assets &lt;directory&gt; [--port N] [--join-origin URL] [--multi-session]</code></td><td>服务本地浏览器适配器；host --ipc 必须在运行</td></tr><tr><td><code>tiktools web --print-code [--port N]</code></td><td>不重启打印当前配对码</td></tr><tr><td><code>tiktools web --reset-session [--port N]</code></td><td>撤销所有已配对浏览器并打印新配对码 <strong>破坏性</strong></td></tr></tbody></table><h3 id="约定" tabindex="-1">约定 <a class="header-anchor" href="#约定" aria-label="Permalink to “约定”">​</a></h3><ul><li><strong>主机解析</strong>: 命令通过本地 IPC 对运行中的主机执行；没有主机运行时，它们以 host_unavailable 失败，而不是启动第二个运行时。使用 <code>tiktools --json system info</code> 作为轻量探针：退出码 0 表示主机已响应，退出码 3 表示 IPC 主机不可用。--standalone 改为对隔离的进程内运行时执行命令。</li><li><strong>输出</strong>: stdout 承载结果；诊断输出到 stderr。--json 打印原始结果对象；不带它时，列表每项打印一行。json 值可以使用 @path 从文件读取。人类可读的帮助跟随显示语言环境：TIKTOOLS_LANG 覆盖 LC_ALL/LC_MESSAGES/LANG 链，机器输出保持与语言环境无关。</li><li><strong>退出码</strong>: 0 成功，1 操作错误，2 用法错误，3 传输失败。</li><li><strong>密钥</strong>: live connect/pick 从 --session-cookie 或 TIKTOOLS_SESSION_COOKIE 环境变量读取会话 cookie（标志优先）；该值从不出现在诊断中。api call 除非传入 --secrets-visible，否则会在输出中隐去秘密，并且没有 --confirm 时拒绝破坏性方法。</li></ul><h2 id="operational-details" tabindex="-1">操作细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to “操作细节”">​</a></h2><p>快照从使用 <code>--features local-web</code> 编译的二进制文件重新生成，以便特性门控的领域（cloud、publisher、web）保持完整。<code>docs check</code> 中的来源检查比较每个 Rust 源代码的哈希值，因此任何命令规范的更改都会导致构建失败，直到重新生成契约。正常的文档构建从不运行 Cargo。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/regenerate-control.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/generate-references.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/cli-coverage.ts</span></span></code></pre></div><p>在更改任何命令解析器或规范后运行重新生成，并将片段 diff 的检查作为更改的一部分。使用 <code>help --json</code> 的代理应将架构版本 1 视为加法稳定：新的动词、领域或字段可能会在没有通知的情况下出现；现有键保持其含义不变。</p>`,52)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};